import { Suspense, useState, useEffect } from "react";
import { ErrorBoundary } from "react-error-boundary";
import { getSintomas } from "../../services/getSintomas";
import ChecklistItems from "./ChecklistItems";
import ItemCadastro from "./ItemCadastro";
import BotaoInicio from "../Shared/BotaoInicio";
import "./Checklist.css";
import { useNavigate, useLocation } from "react-router-dom";
import { useAuth } from "../../contexts/AuthContext";
import { api } from "../../services/api";

const promiseSintomas = getSintomas();

interface Props {
  isRapido?: boolean;
}

export default function PreencherChecklist({ isRapido = false }: Props) {
  const [sintomasSelecionados, setSintomasSelecionados] = useState<number[]>([]);
  const [step, setStep] = useState<1 | 2>(1);

  // Para fluxo formal (não rápido)
  const [cpfBusca, setCpfBusca] = useState("");
  const [patientDetails, setPatientDetails] = useState<any>(null);
  const [isLoadingPatient, setIsLoadingPatient] = useState(false);

  // Para fluxo rápido
  const [sexoRapido, setSexoRapido] = useState<"M" | "F" | null>(null);

  // Quem está preenchendo (exigido para contas de paciente/familiares)
  const OPCOES_QUEM_PREENCHE = ["Pai", "Mãe", "Responsável", "Pedagogo", "Psicólogo", "Outro"];
  const [quemPreencheSelecionado, setQuemPreencheSelecionado] = useState("");
  const [quemPreencheOutro, setQuemPreencheOutro] = useState("");

  // Relatório Final (Modal)
  const [reportData, setReportData] = useState<any>(null);

  const navigate = useNavigate();
  const { usuario } = useAuth();

  const location = useLocation();
  const searchParams = new URLSearchParams(location.search);
  const cpfParam = searchParams.get('cpf');

  useEffect(() => {
    // Se for paciente logado, busca os próprios dados automaticamente
    if (!isRapido && usuario && usuario.role === "paciente") {
      setIsLoadingPatient(true);
      api
        .get(`/patients/cpf/${usuario.cpf}`)
        .then((res) => {
          setPatientDetails(res);
          setStep(2);
        })
        .catch(() => {
          alert("Erro ao carregar dados do paciente.");
        })
        .finally(() => setIsLoadingPatient(false));
    } else if (!isRapido && cpfParam) {
      setCpfBusca(cpfParam);
      setIsLoadingPatient(true);
      api
        .get(`/patients/cpf/${cpfParam}`)
        .then((res) => {
          setPatientDetails(res);
          setStep(2);
        })
        .catch(() => {
          alert("Paciente não encontrado pelo CPF passado.");
        })
        .finally(() => setIsLoadingPatient(false));
    }
  }, [usuario, isRapido, cpfParam]);

  const handleBuscarPaciente = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!cpfBusca) return;
    setIsLoadingPatient(true);
    try {
      const res = await api.get(`/patients/cpf/${cpfBusca}`);
      setPatientDetails(res);
      setStep(2);
    } catch (error: any) {
      alert("Paciente não encontrado. Verifique o CPF.");
    } finally {
      setIsLoadingPatient(false);
    }
  };

  const handleStartRapido = (e: React.FormEvent) => {
    e.preventDefault();
    if (sexoRapido) setStep(2);
  };

  const handleSubmit = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();

    const quemPreencheFinal =
      quemPreencheSelecionado === "Outro" ? (quemPreencheOutro.trim() ? `Outro: ${quemPreencheOutro.trim()}` : "") : quemPreencheSelecionado;

    if (!isRapido && usuario?.role === "paciente" && !quemPreencheFinal) {
      alert("Por favor, informe quem está preenchendo o formulário.");
      return;
    }

    if (isRapido) {
      // Checklist rápido - Cálculo local mockado
      const sintomasList = await promiseSintomas;
      const scoreEstimado = sintomasSelecionados.reduce((sum, id) => {
        const s = sintomasList.find((item) => item.id === id);
        if (!s) return sum;
        return sum + (sexoRapido === "M" ? Number(s.peso_M) : Number(s.peso_F));
      }, 0);

      const classificacao = scoreEstimado >= (sexoRapido === "M" ? 0.56 : 0.55) ? "Suspeito" : "Negativo";

      const calculos = sintomasSelecionados
        .map((id) => {
          const s = sintomasList.find((item) => item.id === id);
          return s ? `${s.nome}: ${sexoRapido === "M" ? s.peso_M : s.peso_F}` : "";
        })
        .join("\n");

      setReportData({
        score_final: scoreEstimado,
        classificacao,
        memoria_calculo: calculos,
        sintomas_identificados: sintomasSelecionados.map((id) => sintomasList.find((item) => item.id === id)?.nome),
        isRapido: true,
      });
      return;
    }

    // Fluxo Formal
    const payload = {
      idPaciente: patientDetails.id,
      idMedico: usuario?.role === "medico" ? usuario.id : null,
      preenchidoPor: usuario?.role === "paciente" ? quemPreencheFinal : usuario?.nome || "Anônimo",
      sintomasSelecionados,
    };

    try {
      const result = await api.post("/checklists", payload);

      if (usuario?.role === "paciente") {
        alert("Checklist enviado com sucesso! Seus dados foram salvos com segurança no sistema.");
        navigate("/dashboard");
      } else {
        // Exibir modal para médico/instituto/admin
        setReportData(result);
      }
    } catch (error: any) {
      alert(error.message || "Erro ao salvar o checklist.");
    }
  };

  const isMale = isRapido ? sexoRapido === "M" : patientDetails?.pacienteDetails?.sexo_biologico === "M";

  // Modal Report Render
  const renderReportModal = () => {
    if (!reportData) return null;

    return (
      <div
        style={{
          position: "fixed",
          top: 0,
          left: 0,
          width: "100vw",
          height: "100vh",
          background: "rgba(0,0,0,0.6)",
          backdropFilter: "blur(4px)",
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
          zIndex: 1100,
          padding: "20px",
        }}
      >
        <div
          className="dashboard-med-registration"
          style={{ maxWidth: "600px", width: "100%", background: "#fff", borderRadius: "16px", padding: "32px", maxHeight: "90vh", overflowY: "auto" }}
        >
          <h3 style={{ color: "#1a5fa8", fontSize: "24px", marginBottom: "8px", textAlign: "center" }}>
            {reportData.isRapido ? "Resultado Rápido (Não Salvo)" : "Relatório de Checklist Salvo"}
          </h3>

          <div style={{ marginTop: "24px", padding: "16px", background: "#f8fafc", borderRadius: "8px", border: "1px solid #e2e8f0" }}>
            <h4 style={{ fontSize: "16px", color: "#334155", marginBottom: "12px" }}>Classificação Final</h4>
            <div
              style={{
                fontSize: "20px",
                fontWeight: "bold",
                color: reportData.classificacao === "Suspeito" ? "#ef4444" : "#10b981",
                background: reportData.classificacao === "Suspeito" ? "#fef2f2" : "#ecfdf5",
                padding: "12px",
                borderRadius: "8px",
                textAlign: "center",
                border: `1px solid ${reportData.classificacao === "Suspeito" ? "#fca5a5" : "#6ee7b7"}`,
              }}
            >
              {reportData.classificacao === "Suspeito" ? "⚠️ Suspeito para FXS" : "✅ Negativo"}
            </div>
            <p style={{ marginTop: "8px", fontSize: "13px", color: "#64748b", textAlign: "center" }}>
              Score Total: <strong>{Number(reportData.score_final).toFixed(2)} pts</strong>
            </p>
          </div>

          <div style={{ marginTop: "24px" }}>
            <h4 style={{ fontSize: "16px", color: "#334155", marginBottom: "8px" }}>Memória de Cálculo (Pesos Considerados)</h4>
            <pre
              style={{
                background: "#1e293b",
                color: "#f8fafc",
                padding: "16px",
                borderRadius: "8px",
                fontSize: "13px",
                whiteSpace: "pre-wrap",
                lineHeight: "1.6",
              }}
            >
              {reportData.memoria_calculo || "Nenhum sintoma selecionado."}
            </pre>
          </div>

          <button
            onClick={() => {
              setReportData(null);
              navigate("/dashboard");
            }}
            className="checklist-submit-btn"
            style={{ width: "100%", marginTop: "32px" }}
          >
            Concluir e Voltar ao Dashboard
          </button>
        </div>
      </div>
    );
  };

  return (
    <div
      className="checklist-wrapper"
      style={{ position: "relative" }}
    >
      <button
        type="button"
        onClick={() => navigate(-1)}
        style={{
          position: "absolute",
          top: "24px",
          left: "24px",
          background: "none",
          border: "none",
          color: "#1a5fa8",
          cursor: "pointer",
          fontWeight: "bold",
          fontSize: "14px",
          zIndex: 10,
        }}
      >
        ← Voltar
      </button>

      {renderReportModal()}

      {step === 1 && (
        <div
          className="cadastro-form"
          style={{ maxWidth: "500px", margin: "0 auto" }}
        >
          <div className="checklist-container">
            <h2 className="checklist-title">Passo 1: Identificação</h2>

            {isRapido ? (
              <form onSubmit={handleStartRapido}>
                <p className="checklist-subtitle">Selecione o sexo biológico para aplicar a tabela de pesos correta.</p>
                <div style={{ display: "flex", gap: "16px", marginBottom: "24px" }}>
                  <label style={{ display: "flex", alignItems: "center", gap: "8px", cursor: "pointer" }}>
                    <input
                      type="radio"
                      name="sexo"
                      value="M"
                      onChange={() => setSexoRapido("M")}
                      required
                    />{" "}
                    Masculino
                  </label>
                  <label style={{ display: "flex", alignItems: "center", gap: "8px", cursor: "pointer" }}>
                    <input
                      type="radio"
                      name="sexo"
                      value="F"
                      onChange={() => setSexoRapido("F")}
                      required
                    />{" "}
                    Feminino
                  </label>
                </div>
                <button
                  type="submit"
                  className="checklist-submit-btn"
                  style={{ width: "100%" }}
                >
                  Avançar para Sintomas
                </button>
              </form>
            ) : usuario?.role !== "paciente" ? (
              <form onSubmit={handleBuscarPaciente}>
                <p className="checklist-subtitle">Digite o CPF do paciente para buscar a ficha e o sexo biológico antes de preencher os sintomas.</p>
                <div
                  className="cadastro-item"
                  style={{ marginBottom: "24px" }}
                >
                  <label className="cadastro-label">CPF do Paciente</label>
                  <input
                    type="text"
                    className="cadastro-input"
                    placeholder="Somente números"
                    value={cpfBusca}
                    onChange={(e) => setCpfBusca(e.target.value)}
                    required
                  />
                </div>
                <button
                  type="submit"
                  className="checklist-submit-btn"
                  style={{ width: "100%" }}
                  disabled={isLoadingPatient}
                >
                  {isLoadingPatient ? "Buscando..." : "Buscar Paciente"}
                </button>
              </form>
            ) : (
              <div style={{ textAlign: "center", padding: "20px" }}>
                <p>Carregando seus dados...</p>
              </div>
            )}
          </div>
        </div>
      )}

      {step === 2 && (
        <form
          className="cadastro-form"
          onSubmit={handleSubmit}
        >
          {!isRapido && patientDetails && (
            <div
              className="checklist-container"
              style={{ marginBottom: "24px" }}
            >
              <h2
                className="checklist-title"
                style={{ fontSize: "1.5rem" }}
              >
                Ficha do Paciente
              </h2>
              <div style={{ background: "#f8fafc", padding: "16px", borderRadius: "8px", border: "1px solid #e2e8f0", fontSize: "14px", marginBottom: "16px" }}>
                <p>
                  <strong>Nome:</strong> {patientDetails.nome}
                </p>
                <p>
                  <strong>CPF:</strong> {patientDetails.cpf}
                </p>
                <p>
                  <strong>Sexo Biológico:</strong> {patientDetails.pacienteDetails?.sexo_biologico === "M" ? "Masculino" : "Feminino"}
                </p>
              </div>

              {usuario?.role === "paciente" && (
                <div style={{ display: "flex", flexDirection: "column", gap: "12px" }}>
                  <div
                    className="cadastro-item"
                    style={{ marginBottom: 0 }}
                  >
                    <label className="cadastro-label">Quem está preenchendo o formulário?</label>
                    <select
                      className="cadastro-input"
                      value={quemPreencheSelecionado}
                      onChange={(e) => setQuemPreencheSelecionado(e.target.value)}
                      required
                      style={{ cursor: "pointer" }}
                    >
                      <option
                        value=""
                        disabled
                      >
                        Selecione uma opção
                      </option>
                      {OPCOES_QUEM_PREENCHE.map((op) => (
                        <option
                          key={op}
                          value={op}
                        >
                          {op}
                        </option>
                      ))}
                    </select>
                  </div>

                  {quemPreencheSelecionado === "Outro" && (
                    <div
                      className="cadastro-item"
                      style={{ marginBottom: 0 }}
                    >
                      <label className="cadastro-label">Especifique:</label>
                      <input
                        type="text"
                        className="cadastro-input"
                        placeholder="Ex: Avó, Cuidador, Terapeuta..."
                        value={quemPreencheOutro}
                        onChange={(e) => setQuemPreencheOutro(e.target.value)}
                        required
                      />
                    </div>
                  )}
                </div>
              )}
            </div>
          )}

          <ErrorBoundary
            fallback={
              <div className="checklist-container checklist-error-container">
                <h2 className="checklist-error-title">Ops! Algo deu errado.</h2>
                <button
                  className="checklist-retry-btn"
                  onClick={() => window.location.reload()}
                >
                  Tentar Novamente
                </button>
              </div>
            }
          >
            <Suspense
              fallback={
                <div className="checklist-container">
                  <h2 className="checklist-loading">Carregando checklist...</h2>
                </div>
              }
            >
              <div className="checklist-container">
                <h1 className="checklist-title">{isRapido ? "Checklist Rápido" : "Checklist Clínico (X Frágil)"}</h1>
                <p className="checklist-subtitle">Marque os sintomas identificados no paciente. (Ocultando sintomas incompatíveis com sexo feminino)</p>

                <ChecklistItems
                  promiseSintomas={promiseSintomas.then((list) => list.filter((item) => (isMale ? true : item.nome.toLowerCase() !== "macroorquidismo")))}
                  onChange={setSintomasSelecionados}
                />
              </div>
            </Suspense>
          </ErrorBoundary>

          <div
            className="form-actions"
            style={{ gap: "16px" }}
          >
            <BotaoInicio
              label="Cancelar"
              to="/dashboard"
            />
            <button
              type="submit"
              className="checklist-submit-btn"
            >
              {isRapido ? "Calcular Score (Rápido)" : "Salvar Checklist e Calcular"}
            </button>
          </div>
        </form>
      )}
    </div>
  );
}

import React, { useState, useEffect } from 'react';
import { useSearchParams, useNavigate } from 'react-router-dom';
import { api } from '../../services/api';
import ItemCadastro from '../Checklist/ItemCadastro';
import BotaoInicio from '../Shared/BotaoInicio';
import '../Checklist/Checklist.css';

const ActivateAccount = () => {
  const [searchParams] = useSearchParams();
  const navigate = useNavigate();
  const token = searchParams.get('token');

  const [usuario, setUsuario] = useState<any | null>(null);
  const [loading, setLoading] = useState(true);
  const [password, setPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [errorMessage, setErrorMessage] = useState('');
  const [success, setSuccess] = useState(false);

  useEffect(() => {
    const validate = async () => {
      if (token) {
        try {
          const user = await api.get(`/patients/validar-token?token=${token}`);
          if (user) {
            setUsuario(user);
          }
        } catch (e: any) {
          console.error("Token inválido ou expirado", e);
        }
      }
      setLoading(false);
    };
    validate();
  }, [token]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setErrorMessage('');

    if (!password || !confirmPassword) {
      setErrorMessage('Por favor, preencha todos os campos.');
      return;
    }

    if (password.length < 6) {
      setErrorMessage('A senha deve conter no mínimo 6 caracteres.');
      return;
    }

    if (password !== confirmPassword) {
      setErrorMessage('As senhas não coincidem.');
      return;
    }

    const submit = async () => {
      if (token) {
        try {
          await api.post('/patients/ativar-conta', { token, senha: password });
          setSuccess(true);
        } catch (e: any) {
          setErrorMessage(e.response?.data?.error || 'Erro ao tentar ativar a conta. Link expirado ou inválido.');
        }
      }
    };
    submit();
  };

  if (loading) {
    return (
      <div className="checklist-wrapper">
        <div className="checklist-container">
          <h2 className="checklist-loading">Validando convite de ativação...</h2>
        </div>
      </div>
    );
  }

  if (success) {
    return (
      <div className="checklist-wrapper" style={{ display: 'flex', justifyContent: 'center', alignItems: 'center' }}>
        <div className="checklist-container" style={{ maxWidth: '500px', width: '100%', textAlign: 'center', padding: '40px' }}>
          <div style={{ fontSize: '48px', color: '#52c41a', marginBottom: '16px' }}>✓</div>
          <h1 className="checklist-title">Conta Ativada!</h1>
          <p className="checklist-subtitle" style={{ marginBottom: '28px' }}>
            Sua conta foi ativada com sucesso. Você já pode fazer login no sistema do Instituto Buko Kaesemodel usando seu e-mail ou CPF e a senha que acabou de cadastrar.
          </p>
          <button
            type="button"
            className="checklist-submit-btn"
            style={{ width: '100%' }}
            onClick={() => navigate('/login')}
          >
            Acessar o Sistema
          </button>
        </div>
      </div>
    );
  }

  if (!usuario) {
    return (
      <div className="checklist-wrapper" style={{ display: 'flex', justifyContent: 'center', alignItems: 'center' }}>
        <div className="checklist-container" style={{ maxWidth: '500px', width: '100%', textAlign: 'center', padding: '40px' }}>
          <div style={{ fontSize: '48px', color: '#ff4d4f', marginBottom: '16px' }}>⚠</div>
          <h1 className="checklist-title">Convite Inválido</h1>
          <p className="checklist-subtitle" style={{ marginBottom: '28px' }}>
            O link de ativação é inválido ou já foi utilizado. Caso precise de um novo link, entre em contato com o médico responsável ou suporte do Instituto.
          </p>
          <BotaoInicio label="Voltar ao Início" />
        </div>
      </div>
    );
  }

  return (
    <div className="checklist-wrapper" style={{ position: 'relative' }}>
      <button
        type="button"
        onClick={() => navigate(-1)}
        style={{ position: 'absolute', top: '24px', left: '24px', background: 'none', border: 'none', color: '#1a5fa8', cursor: 'pointer', fontWeight: 'bold', fontSize: '14px', zIndex: 10 }}
      >
        ← Voltar
      </button>
      <form onSubmit={handleSubmit} className="cadastro-form" style={{ maxWidth: '500px', width: '100%', marginTop: '32px' }}>
        <div className="checklist-container" style={{ marginBottom: '24px' }}>
          <h1 className="checklist-title">Ativar Conta</h1>
          <p className="checklist-subtitle">
            Olá, <strong>{usuario.nome}</strong>! Defina sua senha abaixo para concluir a ativação de sua conta de {usuario.role === 'medico' ? 'Médico Parceiro' : 'Paciente'}.
          </p>

          <p style={{ fontSize: '13px', color: '#666', background: 'rgba(0,0,0,0.03)', padding: '10px', borderRadius: '6px', marginBottom: '20px' }}>
            <strong>Usuário (E-mail):</strong> {usuario.email}<br />
            {usuario.cpf && usuario.cpf !== '00000000000' && (
              <><strong>CPF:</strong> {usuario.cpf}</>
            )}
          </p>

          {errorMessage && (
            <div style={{
              background: 'rgba(255, 77, 79, 0.15)',
              border: '1px solid #ff4d4f',
              color: '#ff4d4f',
              padding: '12px',
              borderRadius: '8px',
              fontSize: '13px',
              marginBottom: '16px',
              textAlign: 'center'
            }}>
              {errorMessage}
            </div>
          )}

          <div style={{ display: 'flex', flexDirection: 'column', gap: '16px' }}>
            <div className="cadastro-item" style={{ width: '100%' }}>
              <label className="cadastro-label">Nova Senha</label>
              <input
                type="password"
                className="cadastro-input"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                placeholder="Mínimo 6 caracteres"
                required
              />
            </div>
            <div className="cadastro-item" style={{ width: '100%' }}>
              <label className="cadastro-label">Confirmar Senha</label>
              <input
                type="password"
                className="cadastro-input"
                value={confirmPassword}
                onChange={(e) => setConfirmPassword(e.target.value)}
                placeholder="Repita a senha"
                required
              />
            </div>
          </div>
        </div>

        <div className="form-actions" style={{ gap: '16px' }}>
          <BotaoInicio label="Cancelar" to="/dashboard" />
          <button type="submit" className="checklist-submit-btn">
            Ativar Minha Conta
          </button>
        </div>
      </form>
    </div>
  );
};

export default ActivateAccount;

import React, { useState } from "react";
import { useAuth } from "../../contexts/AuthContext";
import { api } from "../../services/api";

export default function AdminMedics() {
  const { usuario } = useAuth();

  const [nomeCompleto, setNomeCompleto] = useState("");
  const [crm, setCrm] = useState("");
  const [especialidade, setEspecialidade] = useState("");
  const [email, setEmail] = useState("");
  const [telefone, setTelefone] = useState("");
  const [cidade, setCidade] = useState("");
  const [estado, setEstado] = useState("");
  const [instituicao, setInstituicao] = useState("");
  const [senha, setSenha] = useState("");
  const [cpf, setCpf] = useState("");

  const [error, setError] = useState("");
  const [success, setSuccess] = useState(false);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError("");
    setSuccess(false);

    if (!usuario) {
      setError("Ação não autorizada. Faça login novamente.");
      return;
    }

    if (cpf && (cpf.length !== 11 || /^\d{11}$/.test(cpf) === false)) {
      setError("CPF Inválido.");
      return;
    }

    try {
      await api.post("/doctors/registrar-direto", {
        nomeCompleto,
        crm,
        especialidade,
        email,
        telefone,
        cidade,
        estado,
        instituicao,
        senha,
        cpf,
        adminUser: {
          id: usuario.id,
          nome: usuario.nome,
          role: usuario.role || "admin",
        },
      });

      setSuccess(true);
      // Reset form
      setNomeCompleto("");
      setCrm("");
      setEspecialidade("");
      setEmail("");
      setTelefone("");
      setCidade("");
      setEstado("");
      setInstituicao("");
      setSenha("");
      setCpf("");

      // Auto-hide success alert
      setTimeout(() => {
        setSuccess(false);
      }, 5000);
    } catch (err: any) {
      setError(err.message || "Erro ao registrar médico.");
    }
  };

  return (
    <div style={{ padding: "24px", maxWidth: "800px", margin: "0 auto" }}>
      <div style={{ marginBottom: "24px" }}>
        <h2 style={{ fontSize: "24px", fontWeight: "bold", color: "#ffffff", marginBottom: "8px" }}>Registrar Novo Médico</h2>
        <p style={{ color: "rgba(255,255,255,0.8)", fontSize: "14px" }}>
          Cadastre uma conta de médico ativada diretamente no sistema. Ele poderá acessar imediatamente utilizando o e-mail ou CRM e a senha cadastrada.
        </p>
      </div>

      {error && (
        <div
          style={{
            background: "rgba(255, 77, 79, 0.15)",
            border: "1px solid #ff4d4f",
            color: "#ff4d4f",
            padding: "12px 16px",
            borderRadius: "8px",
            fontSize: "14px",
            marginBottom: "20px",
            fontWeight: "500",
          }}
        >
          {error}
        </div>
      )}

      {success && (
        <div
          style={{
            background: "rgba(82, 196, 26, 0.15)",
            border: "1px solid #52c41a",
            color: "#52c41a",
            padding: "12px 16px",
            borderRadius: "8px",
            fontSize: "14px",
            marginBottom: "20px",
            fontWeight: "500",
          }}
        >
          Médico cadastrado com sucesso! A conta está ativa e pronta para uso.
        </div>
      )}

      <form
        onSubmit={handleSubmit}
        style={{
          background: "#fff",
          padding: "28px",
          borderRadius: "12px",
          boxShadow: "0 4px 6px -1px rgba(0,0,0,0.05), 0 2px 4px -1px rgba(0,0,0,0.03)",
          display: "flex",
          flexDirection: "column",
          gap: "20px",
        }}
      >
        <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: "20px" }}>
          <div
            className="cadastro-item"
            style={{ width: "100%" }}
          >
            <label className="cadastro-label">Nome Completo *</label>
            <input
              type="text"
              className="cadastro-input"
              value={nomeCompleto}
              onChange={(e) => setNomeCompleto(e.target.value)}
              placeholder="Dr(a). Nome Sobrenome"
              required
            />
          </div>

          <div
            className="cadastro-item"
            style={{ width: "100%" }}
          >
            <label className="cadastro-label">CRM *</label>
            <input
              type="text"
              className="cadastro-input"
              value={crm}
              onChange={(e) => setCrm(e.target.value)}
              placeholder="Ex: CRM-12345"
              required
            />
          </div>

          <div
            className="cadastro-item"
            style={{ width: "100%" }}
          >
            <label className="cadastro-label">E-mail *</label>
            <input
              type="email"
              className="cadastro-input"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              placeholder="medico@email.com"
              required
            />
          </div>

          <div
            className="cadastro-item"
            style={{ width: "100%" }}
          >
            <label className="cadastro-label">CPF (Opcional)</label>
            <input
              type="text"
              className="cadastro-input"
              value={cpf}
              onChange={(e) => setCpf(e.target.value)}
              placeholder="Apenas números (Ex: 12345678901)"
            />
          </div>

          <div
            className="cadastro-item"
            style={{ width: "100%" }}
          >
            <label className="cadastro-label">Especialidade *</label>
            <input
              type="text"
              className="cadastro-input"
              value={especialidade}
              onChange={(e) => setEspecialidade(e.target.value)}
              placeholder="Ex: Neuropediatra, Geneticista..."
              required
            />
          </div>

          <div
            className="cadastro-item"
            style={{ width: "100%" }}
          >
            <label className="cadastro-label">Telefone</label>
            <input
              type="tel"
              className="cadastro-input"
              value={telefone}
              onChange={(e) => setTelefone(e.target.value)}
              placeholder="(41) 99999-9999"
            />
          </div>

          <div
            className="cadastro-item"
            style={{ width: "100%" }}
          >
            <label className="cadastro-label">Instituição de Saúde</label>
            <input
              type="text"
              className="cadastro-input"
              value={instituicao}
              onChange={(e) => setInstituicao(e.target.value)}
              placeholder="Ex: Hospital Pequeno Príncipe"
            />
          </div>

          <div
            className="cadastro-item"
            style={{ width: "100%" }}
          >
            <label className="cadastro-label">Senha de Acesso Inicial *</label>
            <input
              type="password"
              className="cadastro-input"
              value={senha}
              onChange={(e) => setSenha(e.target.value)}
              placeholder="Mínimo 6 caracteres"
              required
              minLength={6}
            />
          </div>

          <div
            className="cadastro-item"
            style={{ width: "100%" }}
          >
            <label className="cadastro-label">Cidade</label>
            <input
              type="text"
              className="cadastro-input"
              value={cidade}
              onChange={(e) => setCidade(e.target.value)}
              placeholder="Ex: Curitiba"
            />
          </div>

          <div
            className="cadastro-item"
            style={{ width: "100%" }}
          >
            <label className="cadastro-label">Estado (UF)</label>
            <input
              type="text"
              className="cadastro-input"
              value={estado}
              onChange={(e) => setEstado(e.target.value)}
              placeholder="Ex: PR"
              maxLength={2}
            />
          </div>
        </div>

        <div style={{ marginTop: "12px", display: "flex", gap: "12px", justifyContent: "flex-end" }}>
          <button
            type="submit"
            className="checklist-submit-btn"
            style={{ width: "auto", padding: "12px 32px", margin: 0 }}
          >
            Cadastrar e Ativar Médico
          </button>
        </div>
      </form>
    </div>
  );
}

import React, { useState } from "react";
import { api } from "../../services/api";

export default function AdminRegisterEmployee() {
  const [nome, setNome] = useState("");
  const [email, setEmail] = useState("");
  const [cpf, setCpf] = useState("");
  const [telefone, setTelefone] = useState("");
  const [senha, setSenha] = useState("");
  const [confirmarSenha, setConfirmarSenha] = useState("");
  const [successMessage, setSuccessMessage] = useState("");
  const [errorMessage, setErrorMessage] = useState("");

  const handleRegister = async (e: React.FormEvent) => {
    e.preventDefault();
    setSuccessMessage("");
    setErrorMessage("");

    if (senha !== confirmarSenha) {
      setErrorMessage("As senhas não coincidem.");
      return;
    }

    if (cpf.length !== 11 || /^\d{11}$/.test(cpf) === false) {
      setErrorMessage("CPF Inválido.");
      return;
    }

    try {
      await api.post("/users/employee", {
        nome,
        email,
        cpf,
        telefone,
        senha,
      });
      setSuccessMessage(`Funcionário ${nome} cadastrado com sucesso!`);
      setNome("");
      setEmail("");
      setCpf("");
      setTelefone("");
      setSenha("");
      setConfirmarSenha("");
    } catch (error: any) {
      if (error.message) {
        setErrorMessage(error.message);
      } else {
        setErrorMessage("Erro ao cadastrar funcionário. Verifique os dados e tente novamente.");
      }
    }
  };

  return (
    <div style={{ padding: "24px", maxWidth: "800px", margin: "0 auto" }}>
      <div style={{ marginBottom: "24px" }}>
        <h2 style={{ fontSize: "24px", fontWeight: "bold", color: "#ffffff", marginBottom: "8px" }}>Cadastrar Novo Funcionário</h2>
        <p style={{ color: "rgba(255,255,255,0.8)", fontSize: "14px" }}>
          Registre contas de administração ou funcionários da instituição.
        </p>
      </div>

      {successMessage && (
        <div
          style={{
            background: "rgba(82, 196, 26, 0.15)",
            border: "1px solid #52c41a",
            color: "#52c41a",
            padding: "12px 16px",
            borderRadius: "8px",
            fontSize: "14px",
            marginBottom: "20px",
            fontWeight: "500",
          }}
        >
          {successMessage}
        </div>
      )}

      {errorMessage && (
        <div
          style={{
            background: "rgba(255, 77, 79, 0.15)",
            border: "1px solid #ff4d4f",
            color: "#ff4d4f",
            padding: "12px 16px",
            borderRadius: "8px",
            fontSize: "14px",
            marginBottom: "20px",
            fontWeight: "500",
          }}
        >
          {errorMessage}
        </div>
      )}

      <div
        style={{
          background: "#fff",
          padding: "24px",
          borderRadius: "12px",
          boxShadow: "0 4px 6px -1px rgba(0,0,0,0.05)",
        }}
      >
        <form
          onSubmit={handleRegister}
          style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: "20px" }}
        >
          <div
            className="cadastro-item"
            style={{ gridColumn: "span 2" }}
          >
            <label className="cadastro-label">Nome Completo</label>
            <input
              type="text"
              className="cadastro-input"
              value={nome}
              onChange={(e) => setNome(e.target.value)}
              placeholder="Digite o nome completo"
              required
            />
          </div>

          <div className="cadastro-item">
            <label className="cadastro-label">E-mail Corporativo</label>
            <input
              type="email"
              className="cadastro-input"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              placeholder="exemplo@instituto.com"
              required
            />
          </div>

          <div className="cadastro-item">
            <label className="cadastro-label">CPF</label>
            <input
              type="text"
              className="cadastro-input"
              value={cpf}
              onChange={(e) => setCpf(e.target.value)}
              placeholder="000.000.000-00"
              required
            />
          </div>

          <div
            className="cadastro-item"
            style={{ gridColumn: "span 2" }}
          >
            <label className="cadastro-label">Telefone (Opcional)</label>
            <input
              type="text"
              className="cadastro-input"
              value={telefone}
              onChange={(e) => setTelefone(e.target.value)}
              placeholder="(00) 00000-0000"
            />
          </div>

          <div className="cadastro-item">
            <label className="cadastro-label">Senha Provisória</label>
            <input
              type="password"
              className="cadastro-input"
              value={senha}
              onChange={(e) => setSenha(e.target.value)}
              placeholder="Digite uma senha"
              required
            />
          </div>

          <div className="cadastro-item">
            <label className="cadastro-label">Confirmar Senha</label>
            <input
              type="password"
              className="cadastro-input"
              value={confirmarSenha}
              onChange={(e) => setConfirmarSenha(e.target.value)}
              placeholder="Confirme a senha"
              required
            />
          </div>

          <div style={{ gridColumn: "span 2", marginTop: "12px" }}>
            <button
              type="submit"
              className="checklist-submit-btn"
              style={{ width: "100%", margin: 0 }}
            >
              Registrar Funcionário
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}

