import React, { useState, useEffect } from 'react';
import { api } from '../../services/api';
import './Dashboard.css';

interface Solicitacao {
  id: number;
  nome: string;
  crm: string;
  especialidade: string;
  cidade: string;
  estado: string;
  email: string;
  telefone: string;
  instituicao: string;
  status: string;
  data_criacao: string;
  motivo_recusa?: string;
}

const DoctorApprovals = () => {
  const [solicitacoes, setSolicitacoes] = useState<Solicitacao[]>([]);
  const [rejectionId, setRejectionId] = useState<number | null>(null);
  const [rejectionReason, setRejectionReason] = useState('');
  
  const [approvalId, setApprovalId] = useState<number | null>(null);
  const [successMessage, setSuccessMessage] = useState<string | null>(null);

  const carregarSolicitacoes = async () => {
    try {
      const data = await api.get<Solicitacao[]>('/doctors/solicitacoes');
      setSolicitacoes(data);
    } catch (error) {
      console.error(error);
    }
  };

  useEffect(() => {
    carregarSolicitacoes();
  }, []);

  const startApprove = (id: number) => {
    setApprovalId(id);
  };

  const confirmApprove = async () => {
    if (approvalId === null) return;
    try {
      await api.post(`/doctors/solicitacoes/${approvalId}/responder`, { aprovar: true });
      await carregarSolicitacoes();
      window.dispatchEvent(new Event('solicitacoesUpdated'));
      setApprovalId(null);
      setSuccessMessage('Médico aprovado com sucesso! A conta agora está ativa para uso no sistema.');
      setTimeout(() => setSuccessMessage(null), 5000);
    } catch (e: any) {
      alert(e.message || 'Erro ao aprovar solicitação.');
      setApprovalId(null);
    }
  };

  const startReject = (id: number) => {
    setRejectionId(id);
    setRejectionReason('');
  };

  const handleRejectSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (rejectionId !== null) {
      try {
        await api.post(`/doctors/solicitacoes/${rejectionId}/responder`, { aprovar: false, motivoRecusa: rejectionReason });
        setRejectionId(null);
        setRejectionReason('');
        await carregarSolicitacoes();
        window.dispatchEvent(new Event('solicitacoesUpdated'));
        alert('Solicitação de médico rejeitada.');
      } catch (e: any) {
        alert(e.message || 'Erro ao rejeitar solicitação.');
      }
    }
  };

  const pendingList = solicitacoes.filter(s => s.status === 'PENDING');
  const pastList = solicitacoes.filter(s => s.status !== 'PENDING');

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '30px' }}>
      
      {/* Modal de Sucesso */}
      {successMessage && (
        <div style={{
          position: 'fixed',
          top: 0, left: 0, width: '100vw', height: '100vh',
          background: 'rgba(0,0,0,0.5)',
          display: 'flex', justifyContent: 'center', alignItems: 'center',
          zIndex: 1100, padding: '20px'
        }}>
          <div className="dashboard-med-registration" style={{ maxWidth: '400px', width: '100%', textAlign: 'center', background: '#fff', padding: '30px', borderRadius: '16px' }}>
            <div style={{ fontSize: '50px', marginBottom: '10px' }}>🎉</div>
            <h3 style={{ color: '#10b981', fontSize: '20px', marginBottom: '16px' }}>Sucesso!</h3>
            <p style={{ color: '#475569', fontSize: '15px', marginBottom: '24px' }}>{successMessage}</p>
            <button onClick={() => setSuccessMessage(null)} className="checklist-submit-btn" style={{ background: '#10b981', width: '100%' }}>
              Fechar
            </button>
          </div>
        </div>
      )}

      {/* Modal de Confirmação de Aprovação */}
      {approvalId !== null && (
        <div style={{
          position: 'fixed', top: 0, left: 0, width: '100vw', height: '100vh',
          background: 'rgba(0,0,0,0.6)', backdropFilter: 'blur(4px)',
          display: 'flex', justifyContent: 'center', alignItems: 'center',
          zIndex: 1100, padding: '20px'
        }}>
          <div className="dashboard-med-registration" style={{ maxWidth: '450px', width: '100%', background: '#fff', borderRadius: '16px', padding: '32px' }}>
            <h3 style={{ color: '#1a5fa8', fontSize: '22px', marginBottom: '16px', textAlign: 'center' }}>Confirmar Aprovação</h3>
            <p style={{ color: '#475569', fontSize: '15px', marginBottom: '24px', textAlign: 'center', lineHeight: '1.5' }}>
              Tem certeza que deseja aprovar este médico?<br/><br/>
              Uma vez aprovado, a conta do médico ficará imediatamente <strong>ativa</strong> e ele poderá fazer login no sistema utilizando as credenciais cadastradas.
            </p>
            <div style={{ display: 'flex', gap: '12px' }}>
              <button onClick={confirmApprove} className="checklist-submit-btn" style={{ flex: 1, background: '#10b981' }}>
                Sim, Aprovar
              </button>
              <button onClick={() => setApprovalId(null)} className="hero-btn-secondary" style={{ flex: 1 }}>
                Cancelar
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Modal para Motivo de Rejeição */}
      {rejectionId !== null && (
        <div style={{
          position: 'fixed',
          top: 0,
          left: 0,
          width: '100vw',
          height: '100vh',
          background: 'rgba(0,0,0,0.5)',
          display: 'flex',
          justifyContent: 'center',
          alignItems: 'center',
          zIndex: 1100,
          padding: '20px'
        }}>
          <form onSubmit={handleRejectSubmit} className="dashboard-med-registration" style={{ maxWidth: '450px', width: '100%' }}>
            <h3 className="dashboard-med-title" style={{ color: '#ff4d4f' }}>Rejeitar Credenciamento</h3>
            <p style={{ fontSize: '13px', color: '#666', marginBottom: '16px' }}>
              Por favor, insira o motivo da rejeição da solicitação deste médico (opcional):
            </p>
            <div className="cadastro-item" style={{ width: '100%', marginBottom: '20px' }}>
              <label className="cadastro-label">Motivo do Indeferimento</label>
              <textarea
                className="cadastro-input"
                style={{ minHeight: '80px', fontFamily: 'inherit', resize: 'vertical' }}
                placeholder="Ex: CRM inválido ou não ativo no CFM."
                value={rejectionReason}
                onChange={(e) => setRejectionReason(e.target.value)}
              />
            </div>
            <div style={{ display: 'flex', gap: '12px' }}>
              <button
                type="submit"
                className="checklist-submit-btn"
                style={{ flex: 1, background: '#ff4d4f', border: 'none', margin: 0 }}
              >
                Confirmar Rejeição
              </button>
              <button
                type="button"
                className="hero-btn-secondary"
                style={{ flex: 1 }}
                onClick={() => setRejectionId(null)}
              >
                Cancelar
              </button>
            </div>
          </form>
        </div>
      )}

      <div>
        <h2 style={{ fontSize: '24px', fontWeight: 'bold', color: '#ffffff', marginBottom: '10px' }}>
          Solicitações de Credenciamento
        </h2>
        <p style={{ fontSize: '14px', color: 'rgba(255,255,255,0.85)' }}>
          Gerencie e aprove o credenciamento de novos médicos parceiros do Instituto.
        </p>
      </div>

      {/* Solicitações Pendentes */}
      <div className="dashboard-med-registration">
        <h3 style={{ fontSize: '18px', color: '#1a3a6e', marginBottom: '16px', fontWeight: 'bold' }}>
          Aprovações Pendentes ({pendingList.length})
        </h3>

        {pendingList.length === 0 ? (
          <p style={{ color: '#888', fontSize: '14px', fontStyle: 'italic' }}>
            Nenhuma solicitação pendente no momento.
          </p>
        ) : (
          <div style={{ display: 'flex', flexDirection: 'column', gap: '16px' }}>
            {pendingList.map(sol => (
              <div
                key={sol.id}
                style={{
                  background: '#f8fafc',
                  border: '1px solid #e2e8f0',
                  borderRadius: '12px',
                  padding: '18px',
                  display: 'flex',
                  flexDirection: 'column',
                  gap: '12px'
                }}
              >
                <div style={{ display: 'flex', justifyContent: 'space-between', flexWrap: 'wrap', gap: '8px' }}>
                  <div>
                    <h4 style={{ margin: 0, color: '#1e293b', fontSize: '16px', fontWeight: 'bold' }}>
                      {sol.nome}
                    </h4>
                    <span style={{ fontSize: '12px', color: '#64748b' }}>
                      CRM: {sol.crm} | Especialidade: {sol.especialidade}
                    </span>
                  </div>
                  <span style={{
                    fontSize: '11px',
                    background: '#fef3c7',
                    color: '#d97706',
                    padding: '4px 8px',
                    borderRadius: '9999px',
                    fontWeight: 'bold',
                    alignSelf: 'flex-start'
                  }}>
                    Aguardando Análise
                  </span>
                </div>

                <div style={{
                  display: 'grid',
                  gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))',
                  gap: '12px',
                  fontSize: '14px',
                  color: '#475569',
                  borderTop: '1px solid #e2e8f0',
                  borderBottom: '1px solid #e2e8f0',
                  padding: '12px 0',
                  background: '#ffffff',
                  borderRadius: '8px'
                }}>
                  <div style={{ padding: '0 8px' }}><strong>📧 E-mail:</strong><br/>{sol.email}</div>
                  <div style={{ padding: '0 8px' }}><strong>📱 Telefone:</strong><br/>{sol.telefone}</div>
                  <div style={{ padding: '0 8px' }}><strong>📍 Cidade/UF:</strong><br/>{sol.cidade} - {sol.estado}</div>
                  <div style={{ padding: '0 8px' }}><strong>🏥 Instituição:</strong><br/>{sol.instituicao}</div>
                </div>

                <div style={{ display: 'flex', gap: '16px', justifyContent: 'flex-end', marginTop: '8px' }}>
                  <button
                    type="button"
                    onClick={() => startApprove(sol.id)}
                    className="checklist-submit-btn"
                    style={{ margin: 0, background: '#10b981', color: 'white', padding: '10px 24px', fontSize: '14px', fontWeight: 'bold', borderRadius: '8px', boxShadow: '0 4px 6px -1px rgba(16, 185, 129, 0.2)', transition: 'all 0.2s ease', cursor: 'pointer' }}
                  >
                    ✅ Aprovar Médico
                  </button>
                  <button
                    type="button"
                    onClick={() => startReject(sol.id)}
                    className="checklist-submit-btn"
                    style={{ margin: 0, background: '#ef4444', color: 'white', padding: '10px 24px', fontSize: '14px', fontWeight: 'bold', borderRadius: '8px', boxShadow: '0 4px 6px -1px rgba(239, 68, 68, 0.2)', transition: 'all 0.2s ease', cursor: 'pointer' }}
                  >
                    ❌ Rejeitar
                  </button>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>

      {/* Histórico de Solicitações (Aprovadas/Rejeitadas) */}
      <div className="dashboard-med-registration">
        <h3 style={{ fontSize: '18px', color: '#1a3a6e', marginBottom: '16px', fontWeight: 'bold' }}>
          Histórico de Decisões
        </h3>

        {pastList.length === 0 ? (
          <p style={{ color: '#888', fontSize: '14px', fontStyle: 'italic' }}>
            Nenhum registro anterior de credenciamento.
          </p>
        ) : (
          <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
            {pastList.map(sol => (
              <div
                key={sol.id}
                style={{
                  background: '#f8fafc',
                  border: '1px solid #e2e8f0',
                  borderRadius: '10px',
                  padding: '14px',
                  display: 'flex',
                  justifyContent: 'space-between',
                  alignItems: 'center',
                  flexWrap: 'wrap',
                  gap: '12px'
                }}
              >
                <div>
                  <h4 style={{ margin: 0, color: '#475569', fontSize: '14px', fontWeight: 'bold' }}>
                    {sol.nome} (CRM: {sol.crm})
                  </h4>
                  <p style={{ margin: 0, fontSize: '12px', color: '#94a3b8' }}>
                    {sol.especialidade} | {sol.cidade} - {sol.estado}
                  </p>
                  {sol.status === 'REJECTED' && (
                    <p style={{ margin: '4px 0 0', fontSize: '11px', color: '#ef4444', fontStyle: 'italic' }}>
                      Motivo: {sol.motivo_recusa}
                    </p>
                  )}
                </div>
                <span style={{
                  fontSize: '11px',
                  background: sol.status === 'APPROVED' ? '#dcfce7' : '#fee2e2',
                  color: sol.status === 'APPROVED' ? '#166534' : '#991b1b',
                  padding: '4px 8px',
                  borderRadius: '9999px',
                  fontWeight: 'bold'
                }}>
                  {sol.status === 'APPROVED' ? 'Aprovado' : 'Rejeitado'}
                </span>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
};

export default DoctorApprovals;

import React, { useState, useEffect } from "react";
import { AnimatePresence, motion } from "motion/react";
import { userService } from "../../services/userService";
import { doctorService } from "../../services/doctorService";
import { MockUsuario, MockMedico } from "../../services/types";
import { useAuth } from "../../contexts/AuthContext";

export default function DoctorList() {
  const { usuario } = useAuth();
  const [doctors, setDoctors] = useState<(MockUsuario & { medicoDetails?: MockMedico })[]>([]);
  const [loading, setLoading] = useState(true);
  
  const [selectedDoctor, setSelectedDoctor] = useState<MockUsuario | null>(null);
  const [doctorPatients, setDoctorPatients] = useState<any[]>([]);
  const [loadingPatients, setLoadingPatients] = useState(false);

  useEffect(() => {
    const fetchDoctors = async () => {
      try {
        const users = await userService.listarTodosUsuarios();
        const medicos = users.filter((u) => u.role === "medico");
        setDoctors(medicos);
      } catch (err) {
        console.error("Erro ao buscar médicos:", err);
      } finally {
        setLoading(false);
      }
    };
    fetchDoctors();
  }, []);

  const handleDoctorClick = async (doc: MockUsuario) => {
    if (usuario?.role !== "instituto" && usuario?.role !== "admin") return;
    
    setSelectedDoctor(doc);
    setLoadingPatients(true);
    try {
      const patients = await doctorService.listarPacientesDoMedico(doc.id);
      setDoctorPatients(patients);
    } catch (err) {
      console.error("Erro ao buscar pacientes do médico:", err);
      setDoctorPatients([]);
    } finally {
      setLoadingPatients(false);
    }
  };

  if (loading) {
    return <div style={{ padding: "40px", textAlign: "center", color: "#64748b" }}>Carregando lista de médicos...</div>;
  }

  const canViewPatients = usuario?.role === "instituto" || usuario?.role === "admin";

  return (
    <div style={{ padding: "24px", maxWidth: "1000px", margin: "0 auto", position: "relative" }}>
      <div style={{ marginBottom: "24px" }}>
        <h2 style={{ fontSize: "24px", fontWeight: "bold", color: "#ffffff", marginBottom: "8px" }}>Médicos Cadastrados</h2>
        <p style={{ color: "rgba(255,255,255,0.8)", fontSize: "14px" }}>Lista de todos os médicos credenciados na plataforma.</p>
        {canViewPatients && (
          <p style={{ color: "#60a5fa", fontSize: "13px", marginTop: "4px" }}>Clique em um médico para ver os pacientes que ele tem acesso.</p>
        )}
      </div>

      {doctors.length === 0 ? (
        <div style={{ padding: "40px", textAlign: "center", background: "#fff", borderRadius: "12px", border: "1px dashed #cbd5e1", color: "#64748b" }}>
          Nenhum médico cadastrado no momento.
        </div>
      ) : (
        <AnimatePresence>
          {doctors.map((doc, index) => (
            <motion.div
              key={doc.id}
              onClick={() => handleDoctorClick(doc)}
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              exit={{ opacity: 0, scale: 0.9 }}
              transition={{ duration: 0.2, delay: index * 0.05 }}
              style={{
                background: "#fff",
                padding: "24px",
                borderRadius: "12px",
                marginBottom: "16px",
                boxShadow: "0 4px 6px -1px rgba(0,0,0,0.1), 0 2px 4px -1px rgba(0,0,0,0.06)",
                display: "flex",
                justifyContent: "space-between",
                alignItems: "center",
                borderLeft: "6px solid #3b82f6",
                cursor: canViewPatients ? "pointer" : "default",
              }}
            >
              <div>
                <h3 style={{ margin: "0 0 8px 0", fontSize: "18px", color: "#0f172a", fontWeight: "bold" }}>{doc.nome}</h3>
                <div style={{ display: "flex", gap: "20px", fontSize: "14px", color: "#64748b" }}>
                  <span>
                    <strong>E-mail:</strong> {doc.email}
                  </span>
                  <span>
                    <strong>CRM:</strong> {doc.medicoDetails?.crm || "Não informado"}
                  </span>
                  <span>
                    <strong>Telefone:</strong> {doc.telefone || "Não informado"}
                  </span>
                </div>
              </div>
              <div style={{ textAlign: "right" }}>
                <span
                  style={{
                    display: "inline-block",
                    padding: "6px 12px",
                    borderRadius: "999px",
                    fontSize: "12px",
                    fontWeight: "bold",
                    background: doc.status === "ACTIVE" ? "#dcfce7" : "#fef3c7",
                    color: doc.status === "ACTIVE" ? "#166534" : "#92400e",
                  }}
                >
                  {doc.status === "ACTIVE" ? "Ativo" : "Pendente"}
                </span>
                <p style={{ margin: "8px 0 0 0", fontSize: "13px", color: "#64748b" }}>{doc.medicoDetails?.especialidade || "Clínico Geral"}</p>
              </div>
            </motion.div>
          ))}
        </AnimatePresence>
      )}

      {selectedDoctor && (
        <div style={{
          position: "fixed",
          top: 0,
          left: 0,
          width: "100vw",
          height: "100vh",
          background: "rgba(0,0,0,0.6)",
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
          zIndex: 1000
        }} onClick={() => setSelectedDoctor(null)}>
          <div style={{
            background: "#fff",
            padding: "24px",
            borderRadius: "12px",
            width: "90%",
            maxWidth: "600px",
            maxHeight: "80vh",
            overflowY: "auto"
          }} onClick={e => e.stopPropagation()}>
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", borderBottom: "1px solid #e2e8f0", paddingBottom: "12px", marginBottom: "16px" }}>
              <h3 style={{ margin: 0, color: "#1e293b" }}>Pacientes de {selectedDoctor.nome}</h3>
              <button onClick={() => setSelectedDoctor(null)} style={{ background: "transparent", border: "none", fontSize: "24px", cursor: "pointer", color: "#64748b" }}>&times;</button>
            </div>
            
            {loadingPatients ? (
              <p style={{ textAlign: "center", color: "#64748b" }}>Carregando pacientes...</p>
            ) : doctorPatients.length === 0 ? (
              <p style={{ textAlign: "center", color: "#64748b" }}>Este médico não tem acesso a nenhum paciente.</p>
            ) : (
              <ul style={{ listStyle: "none", padding: 0, margin: 0 }}>
                {doctorPatients.map(p => (
                  <li key={p.id} style={{ padding: "12px", borderBottom: "1px solid #f1f5f9", display: "flex", justifyContent: "space-between" }}>
                    <span style={{ fontWeight: "bold", color: "#334155" }}>{p.nome}</span>
                    <span style={{ color: "#94a3b8", fontSize: "14px" }}>CPF: {p.cpf}</span>
                  </li>
                ))}
              </ul>
            )}
          </div>
        </div>
      )}
    </div>
  );
}

